SELECT COUNT(DISTINCT s.id) AS selectedStoreCount,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{startDate} AND #{endDate}
                         THEN ad.gross_sales_amount ELSE 0 END), 0) AS currentGrossSales,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{previousStartDate} AND #{previousEndDate}
                         THEN ad.gross_sales_amount ELSE 0 END), 0) AS previousGrossSales,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{startDate} AND #{endDate}
                         THEN ad.net_sales_amount ELSE 0 END), 0) AS currentNetSales,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{previousStartDate} AND #{previousEndDate}
                         THEN ad.net_sales_amount ELSE 0 END), 0) AS previousNetSales,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{startDate} AND #{endDate}
                         THEN ad.valid_order_count ELSE 0 END), 0) AS currentOrderCount,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{previousStartDate} AND #{previousEndDate}
                         THEN ad.valid_order_count ELSE 0 END), 0) AS previousOrderCount,
       MAX(ad.updated_at) AS dataUpdatedAt
FROM store_info s
LEFT JOIN analysis_store_daily ad ON ad.store_id = s.id
  AND ad.biz_date BETWEEN #{previousStartDate} AND #{endDate}
WHERE

SELECT s.id AS storeId, s.store_name AS storeName,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{startDate} AND #{endDate}
                         THEN ad.gross_sales_amount ELSE 0 END), 0) AS currentGrossSales,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{previousStartDate} AND #{previousEndDate}
                         THEN ad.gross_sales_amount ELSE 0 END), 0) AS previousGrossSales,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{startDate} AND #{endDate}
                         THEN ad.net_sales_amount ELSE 0 END), 0) AS currentNetSales,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{previousStartDate} AND #{previousEndDate}
                         THEN ad.net_sales_amount ELSE 0 END), 0) AS previousNetSales,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{startDate} AND #{endDate}
                         THEN ad.valid_order_count ELSE 0 END), 0) AS currentOrderCount,
       COALESCE(SUM(CASE WHEN ad.biz_date BETWEEN #{previousStartDate} AND #{previousEndDate}
                         THEN ad.valid_order_count ELSE 0 END), 0) AS previousOrderCount
FROM store_info s
LEFT JOIN analysis_store_daily ad ON ad.store_id = s.id
  AND ad.biz_date BETWEEN #{previousStartDate} AND #{endDate}
WHERE 
GROUP BY s.id, s.store_name
